import { Button, TextField } from "@mui/material"
import FilterComp from "./filterComp"
import data from "../../mockData/products.json"
import Header from "../header/header"
import styled from 'styled-components';
import { FontAwesomeIcon } from "@fortawesome/react-fontawesome"
import { faGear } from "@fortawesome/free-solid-svg-icons"
import SelectLabels from "../../componnets/selectBox";



const Products = () => {
  console.log(data)

  const Categories = [{
    heading: "Categories",
    title: ["Family Nestos", "Your friendly neighood stay",]
  }]
  const collections = [{
    heading: "Collections",
    title: ["Family Nestos", "Your friendly neighood RoomService", "For group travelrer", "Local ids accepted", "nestos well come couples",]
  }]
  const hotelFacility = [{
    heading: "HotelFacility",
    title: ["Fridze", "TV", "bed"]
  }]
  const accomidationType = [{
    heading: "AccomidationType",
    title: ["nesto  home", "hotel"]
  }]

  const checkInFeautures = [{
    heading: "Check-in features",
    title: ["Pay At Hotel",]
  }]

  return (
    <div style={{ fontFamily: "Inter, sans-serif" }}>
      {/* head section */}
      <Header />
      {/* body section */}
      <section className="flex bgAsh">

        {/* left side  */}
        <aside className="bgWhite w-[20%] hide-scrollbar p-2 ml-[5rem] mt-[1rem] mr-[1px]" style={{ height: "60rem", overflow: "auto" }}>
          <Background>
            <div>
              <div className="p-[5rem]">
                <button type="button" class="borderOrange bgWhite align-center h-[2rem] py-2  px-5 me-2 mb-2 text-sm font-medium text-gray-900  rounded-lg  hover:bg-gray-100  focus:z-10 focus:ring-4 focus:ring-gray-100 dark:focus:ring-gray-700 dark:bg-gray-800 dark:text-gray-400 dark:border-gray-600 dark:hover:text-white dark:hover:bg-gray-700">Search</button>
              </div>
            </div>
          </Background>
          <div className="m-2 p-2"><TextField id="outlined-basic" label="Outlined" variant="outlined" className="w-full" /></div>
          <FilterComp det={collections} />
          <FilterComp det={Categories} />
          <FilterComp det={hotelFacility} />
          <FilterComp det={accomidationType} />
          <FilterComp det={checkInFeautures} />

        </aside>


        {/* right side */}
        <section className=" w-[80%] hide-scrollbar p-2 mt-[1rem] " style={{ height: "60rem", overflow: "auto" }}>
          <div>
            <div><span>Home > Hotels more in Goa</span></div>
            <div className=" py-3 flex">
              <h3 className="ml-2">3128 Properties in Goa  </h3>
              <button type="button" class="borderOrange bgWhite align-center h-[2rem] py-2  px-5 me-2 mb-2 text-sm font-medium text-gray-900  rounded-lg  hover:bg-gray-100  focus:z-10 focus:ring-4 focus:ring-gray-100 dark:focus:ring-gray-700 dark:bg-gray-800 dark:text-gray-400 dark:border-gray-600 dark:hover:text-white dark:hover:bg-gray-700">Explore travel tips-></button>
            </div>
          </div>
          <div className="flex bgWhite justify-between mb-3 py-2">
            <div className="flex justify-around">
              <p>SORT BY</p>
              <button>popular</button>
            </div>
            <div><p>User Rating (Highest first)</p></div>
            <div>Price (Highest first)</div>
            <div>Price (lowest first)</div>
          </div>

          
        </section>
      </section>
    </div>
  )
}

export default Products

const Background = styled.div`
  background-image: url("https://imgak.mmtcdn.com/pwa_v3/pwa_hotel_assets/mapEntryHover.png");
  background-size: cover;
  background-position: center;
  height: 8rem;
  font-family: "Inter, sans-serif" !important
`;
